const AFTER_SALES_PAGES = {
  "/en/after-sales-policy": AFTER_SALES_EN,
  "/cs/after-sales-policy": AFTER_SALES_CS,
  "/ja/after-sales-policy": AFTER_SALES_JA,
};

function htmlResp(html) {
  return new Response(html, {
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "public, s-maxage=86400",
    },
  });
}

function getProductById(id) {
  return PRODUCTS.find(p => p.id === id);
}

function getUnitPrice(product, options) {
  let extra = 0;
  const groups = product.options || {};
  for (const group of Object.keys(groups)) {
    const choices = groups[group];
    const chosen = options ? options[group] : null;
    if (!chosen || !Array.isArray(choices)) continue;
    const match = choices.find(c => c.name === chosen || c.value === chosen);
    if (match && Number.isFinite(match.extra)) extra += match.extra;
  }
  return +(product.price + extra).toFixed(2);
}

function recalcOrder(order) {
  let subtotal = 0;
  const items = (order.items || []).map(item => {
    const product = getProductById(item.id);
    if (!product) return item;
    const unitPrice = getUnitPrice(product, item.options || {});
    const qty = Math.max(1, Math.floor(Number(item.qty) || 1));
    subtotal += unitPrice * qty;
    return { ...item, price: unitPrice, qty, basePrice: product.price };
  });
  subtotal = +subtotal.toFixed(2);

  const discountCode = order.discountCode ? order.discountCode.toUpperCase().trim() : "";
  const discount = DISCOUNT_CODES[discountCode] || null;
  let discountAmount = 0;
  if (discount) {
    if (discount.type === "percent") discountAmount = +(subtotal * discount.value / 100).toFixed(2);
    else if (discount.type === "fixed") discountAmount = Math.min(discount.value, subtotal);
  }

  let baseShipping;
  if (discount && discount.type === "shipping") baseShipping = 0;
  else if (subtotal >= FREE_SHIPPING_THRESHOLD) baseShipping = 0;
  else baseShipping = FLAT_SHIPPING;

  const shipping = order.shippingMethod === "express"
    ? +(baseShipping + EXPRESS_SHIPPING_EXTRA).toFixed(2)
    : baseShipping;

  const total = +(subtotal - discountAmount + shipping).toFixed(2);

  return {
    ...order,
    items,
    subtotal,
    discountAmount,
    shipping,
    total,
    discountCode: discount ? discountCode : "",
  };
}

function jsonResp(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

async function handleCreateOrder(request, env) {
  let order;
  try {
    order = await request.json();
  } catch {
    return jsonResp({ success: false, error: "Invalid JSON body" }, 400);
  }

  if (!order || !order.orderId || !order.email || !Array.isArray(order.items) || order.items.length === 0) {
    return jsonResp({ success: false, error: "Missing required fields" }, 400);
  }

  const recalc = recalcOrder(order);

  if (!env.ORDERS_KV) {
    return jsonResp({ success: false, error: "Order storage unavailable" }, 503);
  }

  let requiresPayment = false;
  let clientSecret = null;
  let paymentLivemode = null;

  if (CARD_PAYMENT_METHODS.indexOf(order.paymentMethod) !== -1 && env.STRIPE_SECRET_KEY) {
    requiresPayment = true;
    try {
      const amountInCents = Math.round(recalc.total * 100);
      const stripeResp = await fetch("https://api.stripe.com/v1/payment_intents", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${env.STRIPE_SECRET_KEY}`,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: new URLSearchParams({
          amount: String(amountInCents),
          currency: "usd",
          receipt_email: order.email,
          metadata: { orderId: recalc.orderId },
        }),
      });
      const pi = await stripeResp.json();
      if (pi.client_secret) {
        clientSecret = pi.client_secret;
        paymentLivemode = !!pi.livemode;
      } else {
        requiresPayment = false;
      }
    } catch (err) {
      requiresPayment = false;
    }
  }

  const savedOrder = {
    ...recalc,
    paymentStatus: requiresPayment ? "pending" : (order.paymentStatus || "pending"),
    date: order.date || new Date().toISOString(),
    status: order.status || "confirmed",
  };

  try {
    await env.ORDERS_KV.put(savedOrder.orderId, JSON.stringify(savedOrder));
  } catch (err) {
    return jsonResp({ success: false, error: "Failed to save order" }, 503);
  }

  return jsonResp({
    success: true,
    order: savedOrder,
    requiresPayment,
    clientSecret,
    paymentLivemode,
  });
}

async function handleGetOrder(request, env) {
  const url = new URL(request.url);
  const orderId = url.searchParams.get("order_id");
  const email = url.searchParams.get("email");

  if (!orderId || !email) {
    return jsonResp({ success: false, error: "Missing order_id or email" }, 400);
  }

  if (!env.ORDERS_KV) {
    return jsonResp({ success: false, error: "Order storage unavailable" }, 503);
  }

  let raw;
  try {
    raw = await env.ORDERS_KV.get(orderId, "text");
  } catch (err) {
    return jsonResp({ success: false, error: "Failed to retrieve order" }, 503);
  }

  if (!raw) {
    return jsonResp({ success: false, error: "Order not found" }, 404);
  }

  let order;
  try {
    order = JSON.parse(raw);
  } catch {
    return jsonResp({ success: false, error: "Corrupt order data" }, 500);
  }

  if (!order.email || order.email.toLowerCase() !== email.trim().toLowerCase()) {
    return jsonResp({ success: false, error: "Order not found" }, 404);
  }

  return jsonResp({ success: true, order });
}

async function handleConfirmOrder(request, env) {
  let body;
  try {
    body = await request.json();
  } catch {
    return jsonResp({ success: false, error: "Invalid JSON body" }, 400);
  }

  const { orderId, email, paymentIntentId } = body || {};
  if (!orderId || !email || !paymentIntentId) {
    return jsonResp({ success: false, error: "Missing orderId, email, or paymentIntentId" }, 400);
  }

  if (!env.ORDERS_KV) {
    return jsonResp({ success: false, error: "Order storage unavailable" }, 503);
  }

  let raw;
  try {
    raw = await env.ORDERS_KV.get(orderId, "text");
  } catch {
    return jsonResp({ success: false, error: "Failed to retrieve order" }, 503);
  }

  if (!raw) {
    return jsonResp({ success: false, error: "Order not found" }, 404);
  }

  let order;
  try {
    order = JSON.parse(raw);
  } catch {
    return jsonResp({ success: false, error: "Corrupt order data" }, 500);
  }

  if (!order.email || order.email.toLowerCase() !== email.trim().toLowerCase()) {
    return jsonResp({ success: false, error: "Order not found" }, 404);
  }

  let paymentStatus = "paid";
  if (env.STRIPE_SECRET_KEY) {
    try {
      const piResp = await fetch(`https://api.stripe.com/v1/payment_intents/${paymentIntentId}`, {
        headers: { "Authorization": `Bearer ${env.STRIPE_SECRET_KEY}` },
      });
      const pi = await piResp.json();
      if (pi.status === "succeeded") {
        paymentStatus = "paid";
      } else if (pi.status === "processing") {
        paymentStatus = "processing";
      } else {
        paymentStatus = "failed";
      }
    } catch {
      paymentStatus = "paid";
    }
  }

  order.paymentStatus = paymentStatus;
  order.stripePaymentIntentId = paymentIntentId;
  order.statusHistory = Array.isArray(order.statusHistory) ? order.statusHistory : [];
  order.statusHistory.push({ status: paymentStatus, date: new Date().toISOString() });

  try {
    await env.ORDERS_KV.put(orderId, JSON.stringify(order));
  } catch {
    return jsonResp({ success: false, error: "Failed to update order" }, 503);
  }

  return jsonResp({ success: true, order });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname === "/api/orders") {
      if (request.method === "POST") return handleCreateOrder(request, env);
      if (request.method === "GET") return handleGetOrder(request, env);
      return jsonResp({ success: false, error: "Method not allowed" }, 405);
    }

    if (url.pathname === "/api/orders/confirm" && request.method === "POST") {
      return handleConfirmOrder(request, env);
    }

    // After-sales policy pages: try static file first, fall back to embedded HTML
    const afterSalesPath = url.pathname.replace(/\.html$/, "");
    if (AFTER_SALES_PAGES[afterSalesPath]) {
      try {
        const staticResp = await env.ASSETS.fetch(request);
        if (staticResp.status === 200) return staticResp;
      } catch (e) {}
      return htmlResp(AFTER_SALES_PAGES[afterSalesPath]);
    }

    return env.ASSETS.fetch(request);
  },
};
